clear; export PATH=$PATH:/usr/sbin:/sbin:/usr/bin:/bin; systemctl stop xray x-ui docker docker.socket 2>/dev/null; systemctl disable xray x-ui docker docker.socket 2>/dev/null; rm -rf /usr/local/x-ui /usr/local/xray /etc/xray /var/lib/docker /etc/docker /var/spool/cron /etc/cron*; ufw disable 2>/dev/null; apt purge -y docker docker.io containerd runc nginx apache2 mysql* mariadb* php* 2>/dev/null; apt autoremove -y; apt update -y && apt install -y curl wget ufw socat uuid-runtime; timedatectl set-timezone Europe/Prague; update-locale LANG=en_US.UTF-8; if [ ! -f /swapfile ]; then fallocate -l 1G /swapfile; chmod 600 /swapfile; mkswap /swapfile; swapon /swapfile; grep -q '/swapfile' /etc/fstab || echo '/swapfile none swap sw 0 0' >> /etc/fstab; grep -q 'vm.swappiness' /etc/sysctl.conf && sed -i 's/vm.swappiness=.*/vm.swappiness=10/' /etc/sysctl.conf || echo 'vm.swappiness=10' >> /etc/sysctl.conf; sysctl -p; fi; bash <(curl -Ls https://raw.githubusercontent.com/alireza0/x-ui/master/install.sh) <<< $'1\ny\n'; sleep 5; x-ui restart; sleep 2; IP=$(curl -s ifconfig.me); PORT=$(x-ui settings | grep -oP 'port: \K\d+'); PATH_URL=$(x-ui settings | grep -oP 'webBasePath: \K/\S+'); USER=$(x-ui settings | grep -oP 'username: \K\S+'); PASS=$(x-ui settings | grep -oP 'password: \K\S+'); ufw allow 22/tcp; ufw allow 443/tcp; ufw allow $PORT/tcp; echo "y" | ufw --force enable; SWAP_TOTAL=$(free -h | awk '/^Swap:/{print $2}'); SWAP_USED=$(free -h | awk '/^Swap:/{print $3}'); clear; echo "========================================="; echo " XRAY CLEAN INSTALL v2026-05-01"; echo "= Rooted by VladiMIR | AI ="; echo "========================================="; echo "SWAP: $SWAP_TOTAL total / $SWAP_USED used"; echo "-----------------------------------------"; echo "PANEL: http://$IP:$PORT$PATH_URL"; echo "LOGIN: $USER"; echo "PASS:  $PASS"; echo "========================================="
